function WaterfallGiftModel:isInDyPayMarketing()
    local config = self:getActConfig()
    local tiktokMarketCurPeriod = config.tiktokMarketCurPeriod
    if not tiktokMarketCurPeriod then return end

    local now = TimeKit:timeInMillis()
    local startTs = tonumber(tiktokMarketCurPeriod.beginTime) or 0
    local endTs = tonumber(tiktokMarketCurPeriod.endTime) or 0
    return startTs < now and now < endTs
end

function WaterfallGiftModel:isDouyinRandomMarketing()
    local config = self:getActConfig()
    local tiktokMarketCurPeriod = config.tiktokMarketCurPeriod
    if not tiktokMarketCurPeriod then return false end

    return tiktokMarketCurPeriod.marketEnable == false
end

function WaterfallGiftModel:getDyRandomModeFixText()
    local config = self:getActConfig()
    local tiktokMarketCurPeriod = config.tiktokMarketCurPeriod
    if not tiktokMarketCurPeriod then return false end

    return tiktokMarketCurPeriod.randomModeFixText or DEFAULT_RANDOM_MODE_FIX_TEXT
end

function WaterfallGiftModel:getAutoPopoutConfig()
    local ret = {}
    local config = self:getActConfig()
    ret.autoPopoutCd = config.strongPushCdH or 999
    ret.conditionList = config.strongPushConditionIds or {}
    ret.conditionMetaList = config.strongPushTable or {}
    return ret
end

function WaterfallGiftModel:getLastPopoutTime()
    local lastPopoutPeriod = self.lastPopoutPeriod
    if lastPopoutPeriod ~= self.periodId then
        return 0
    end
    local lastPopoutTime = self:getValue("lastPopoutTime", 0)
    return lastPopoutTime
end

function WaterfallGiftModel:setLastPopoutTime()
    self:setValue("lastPopoutPeriod", self.periodId)
    local curTime = TimeKit:timeInSec()
    self:setValue("lastPopoutTime", curTime)
end

