-- 获取本地缓存的完整key
function WaterfallGiftModel:getLocalKey( key, needTime )
    local str = string.format("%s_%s_%s","waterfallgift", self.periodId, key)
    if needTime then
        local curTime = TimeKit:timeInSec()
        local dayStartTime = getDayStartTimeByTS(curTime)
        str = str .. ':' .. dayStartTime
    end
    return str
end

-- 本地bool缓存
function WaterfallGiftModel:saveFlagToLocalByKey(key, needTime, bool)
    if not key then return end
    if bool == nil then bool = true end
    local keyStr = self:getLocalKey(key, needTime)
    self:setValue("localCache."..keyStr, bool)
end

function WaterfallGiftModel:getFlagFromLocalByKey(key, needTime)
    local keyStr = self:getLocalKey(key, needTime)
    local value = self.localCache[keyStr]
    return value
end

function WaterfallGiftModel:getRealFreeNum()
    local config = self:getActConfig()
    local realFreeNum = 0

    if config.fixRewardNodeList then
        for i,v in ipairs(config.fixRewardNodeList) do
            if v.freeNode then
                realFreeNum = realFreeNum + 1
            else
                break
            end
        end
    end
    return realFreeNum
end

return WaterfallGiftModel
